      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (f : Polynomial R), (Polynomial.taylor 0) f = f"
    },
    {
      "name": "AffineEquiv.constVAdd_zero",
      "module_name": "Mathlib.LinearAlgebra.AffineSpace.AffineEquiv",
      "kind": "theorem",
      "type": "∀ (k : Type u_1) (P₁ : Type u_2) {V₁ : Type u_6} [inst : Ring k] [inst_1 : AddCommGroup V₁] [inst_2 : Module k V₁]\n  [inst_3 : AddTorsor V₁ P₁], AffineEquiv.constVAdd k P₁ 0 = AffineEquiv.refl k P₁"
    },
    {
      "name": "translate_zero",
      "module_name": "Mathlib.Algebra.Group.Translate",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {G : Type u_5} [inst : AddCommGroup G] (f : G → α), translate 0 f = f"
    }
  ]
}

