    {
      "name": "MvPolynomial.aeval_ite_mem_eq_self",
      "module_name": "Mathlib.Algebra.MvPolynomial.Variables",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (q : MvPolynomial σ R) {s : Set σ},\n  ↑q.vars ⊆ s →\n    ∀ [inst_1 : (i : σ) → Decidable (i ∈ s)], (MvPolynomial.aeval fun i => if i ∈ s then MvPolynomial.X i else 0) q = q"
