{
  "items": [
    {
      "name": "MvPolynomial.is_id",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (f : MvPolynomial σ R →+* MvPolynomial σ R),\n  f.comp MvPolynomial.C = MvPolynomial.C →\n    (∀ (n : σ), f (MvPolynomial.X n) = MvPolynomial.X n) → ∀ (p : MvPolynomial σ R), f p = p"
    },
    {
      "name": "MvPolynomial.mapAlgHom_id",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : CommSemiring S₁] [inst_2 : Algebra R S₁],\n  MvPolynomial.mapAlgHom (AlgHom.id R S₁) = AlgHom.id R (MvPolynomial σ S₁)"
    },
    {
      "name": "MvPolynomial.algHom_ext_iff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {A : Type u_2} [inst_1 : Semiring A] [inst_2 : Algebra R A]\n  {f g : MvPolynomial σ R →ₐ[R] A}, f = g ↔ ∀ (i : σ), f (MvPolynomial.X i) = g (MvPolynomial.X i)"
    },
    {
      "name": "MvPolynomial.bind₁_X_left",
      "module_name": "Mathlib.Algebra.MvPolynomial.Monad",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R],\n  MvPolynomial.bind₁ MvPolynomial.X = AlgHom.id R (MvPolynomial σ R)"
    },
    {
      "name": "MvPolynomial.algHom_ext'_iff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {A : Type u_2} {B : Type u_3} [inst_1 : CommSemiring A]\n  [inst_2 : CommSemiring B] [inst_3 : Algebra R A] [inst_4 : Algebra R B] {f g : MvPolynomial σ A →ₐ[R] B},\n  f = g ↔\n    f.comp (IsScalarTower.toAlgHom R A (MvPolynomial σ A)) = g.comp (IsScalarTower.toAlgHom R A (MvPolynomial σ A)) ∧\n      ∀ (i : σ), f (MvPolynomial.X i) = g (MvPolynomial.X i)"
    }
  ]
}
